BEGIN TRANSACTION;
CREATE TABLE alerts (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            alert_id VARCHAR(64) UNIQUE NOT NULL,
            robot_code VARCHAR(16),
            incident_id VARCHAR(64),
            alert_type VARCHAR(32),
            sim_time TIMESTAMP WITH TIME ZONE,
            created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP
        );
CREATE TABLE incidents (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            incident_id VARCHAR(64) UNIQUE NOT NULL,
            event_id VARCHAR(64),
            packet_json TEXT,
            decision_json TEXT,
            trace_json TEXT,
            created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP
        );
CREATE TABLE maintenance_events (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            event_id VARCHAR(64) UNIQUE NOT NULL,
            robot_code VARCHAR(16) NOT NULL,
            event_type VARCHAR(64) NOT NULL,
            description TEXT,
            occurred_at TIMESTAMP WITH TIME ZONE NOT NULL,
            created_at TIMESTAMP WITH TIME ZONE NOT NULL
        );
CREATE TABLE perception_results (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            event_id VARCHAR(64) UNIQUE NOT NULL,
            robot_code VARCHAR(16) NOT NULL,
            program_number INTEGER NOT NULL,
            observed_at TIMESTAMP WITH TIME ZONE NOT NULL,
            abnormal_type VARCHAR(64) NOT NULL,
            abnormal_score REAL NOT NULL,
            severity_hint VARCHAR(16) NOT NULL,
            is_file_anomaly BOOLEAN NOT NULL,
            per_sensor_scores TEXT NOT NULL
        );
CREATE TABLE pm_cards (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            card_id VARCHAR(64) UNIQUE NOT NULL,
            robot_code VARCHAR(16) NOT NULL,
            title VARCHAR(255) NOT NULL,
            description TEXT,
            scheduled_date TIMESTAMP WITH TIME ZONE,
            status VARCHAR(32) NOT NULL DEFAULT 'pending',
            created_at TIMESTAMP WITH TIME ZONE NOT NULL
        );
CREATE INDEX ix_pr_robot_code ON perception_results(robot_code);
CREATE INDEX ix_pr_observed_at ON perception_results(observed_at);
CREATE INDEX ix_pr_abnormal_type ON perception_results(abnormal_type);
CREATE INDEX ix_pr_is_file_anomaly ON perception_results(is_file_anomaly);
DELETE FROM "sqlite_sequence";
COMMIT;
